import React, { useState } from 'react';
import axios from 'axios';

const Dashboard = () => {
  const [features, setFeatures] = useState({
    PM2_5: 75,
    CO: 10,
    NO2: 20,
    NH3: 30,
    O3: 60,
    Temp: 25,
    Humidity: 50,
    Pressure: 1013
  });

  const [result, setResult] = useState(null);

  const handleChange = (e) => {
    setFeatures({ ...features, [e.target.name]: parseFloat(e.target.value) });
  };

  const handlePredict = async () => {
    try {
      const response = await axios.post('http://localhost:5000/predict', {
        'PM2.5': features.PM2_5,
        'CO': features.CO,
        'NO2': features.NO2,
        'NH3': features.NH3,
        'O3': features.O3,
        'Temp': features.Temp,
        'Humidity': features.Humidity,
        'Pressure': features.Pressure
      });
      setResult(response.data.prediction);
    } catch (error) {
      console.error("Prediction error:", error);
      setResult("Error connecting to server");
    }
  };

  return (
    <div style={{ maxWidth: '600px', margin: '0 auto', backgroundColor: '#1e1e1e', color: '#fff', padding: '20px', borderRadius: '12px', fontFamily: 'Arial' }}>
      <h2 style={{ textAlign: 'center' }}>Enter Input Features</h2>

      {/* Sliders */}
      <div style={{ marginBottom: '20px' }}>
        <label>PM2.5 (µg/m³)</label>
        <div style={{ color: 'red', fontWeight: 'bold' }}>{features.PM2_5.toFixed(2)}</div>
        <input type="range" min="0" max="2000" value={features.PM2_5} name="PM2_5" onChange={handleChange} style={{ width: '100%' }} />
        <div style={{ display: 'flex', justifyContent: 'space-between', fontSize: '12px' }}><span>0.00</span><span>2000.00</span></div>
      </div>

      <div style={{ marginBottom: '20px' }}>
        <label>CO (µg/m³)</label>
        <div style={{ color: 'red', fontWeight: 'bold' }}>{features.CO.toFixed(2)}</div>
        <input type="range" min="0" max="58400" value={features.CO} name="CO" onChange={handleChange} style={{ width: '100%' }} />
        <div style={{ display: 'flex', justifyContent: 'space-between', fontSize: '12px' }}><span>0.00</span><span>58400.00</span></div>
      </div>

      <div style={{ marginBottom: '20px' }}>
        <label>NO₂ (µg/m³)</label>
        <div style={{ color: 'red', fontWeight: 'bold' }}>{features.NO2.toFixed(2)}</div>
        <input type="range" min="0" max="3853" value={features.NO2} name="NO2" onChange={handleChange} style={{ width: '100%' }} />
        <div style={{ display: 'flex', justifyContent: 'space-between', fontSize: '12px' }}><span>0.00</span><span>3853.00</span></div>
      </div>

      <div style={{ marginBottom: '20px' }}>
        <label>NH₃ (µg/m³)</label>
        <div style={{ color: 'red', fontWeight: 'bold' }}>{features.NH3.toFixed(2)}</div>
        <input type="range" min="0" max="300" value={features.NH3} name="NH3" onChange={handleChange} style={{ width: '100%' }} />
        <div style={{ display: 'flex', justifyContent: 'space-between', fontSize: '12px' }}><span>0.00</span><span>300.00</span></div>
      </div>

      <div style={{ marginBottom: '20px' }}>
        <label>O₃ (µg/m³)</label>
        <div style={{ color: 'red', fontWeight: 'bold' }}>{features.O3.toFixed(2)}</div>
        <input type="range" min="0" max="2350" value={features.O3} name="O3" onChange={handleChange} style={{ width: '100%' }} />
        <div style={{ display: 'flex', justifyContent: 'space-between', fontSize: '12px' }}><span>0.00</span><span>2350.00</span></div>
      </div>

      <div style={{ marginBottom: '20px' }}>
        <label>Temperature (°C)</label>
        <div style={{ color: 'red', fontWeight: 'bold' }}>{features.Temp.toFixed(2)}</div>
        <input type="range" min="0" max="50" value={features.Temp} name="Temp" onChange={handleChange} style={{ width: '100%' }} />
        <div style={{ display: 'flex', justifyContent: 'space-between', fontSize: '12px' }}><span>0.00</span><span>50.00</span></div>
      </div>

      <div style={{ marginBottom: '20px' }}>
        <label>Humidity (%)</label>
        <div style={{ color: 'red', fontWeight: 'bold' }}>{features.Humidity.toFixed(2)}</div>
        <input type="range" min="0" max="100" value={features.Humidity} name="Humidity" onChange={handleChange} style={{ width: '100%' }} />
        <div style={{ display: 'flex', justifyContent: 'space-between', fontSize: '12px' }}><span>0.00</span><span>100.00</span></div>
      </div>

      <div style={{ marginBottom: '20px' }}>
        <label>Pressure (hPa)</label>
        <div style={{ color: 'red', fontWeight: 'bold' }}>{features.Pressure.toFixed(2)}</div>
        <input type="range" min="900" max="1100" value={features.Pressure} name="Pressure" onChange={handleChange} style={{ width: '100%' }} />
        <div style={{ display: 'flex', justifyContent: 'space-between', fontSize: '12px' }}><span>900.00</span><span>1100.00</span></div>
      </div>

      <button
        onClick={handlePredict}
        style={{
          width: '100%',
          padding: '12px',
          backgroundColor: '#d32f2f',
          color: '#fff',
          border: 'none',
          borderRadius: '6px',
          fontWeight: 'bold',
          fontSize: '16px',
          marginTop: '20px',
          cursor: 'pointer'
        }}
      >
        Predict EAQI
      </button>

      {result && (
        <div style={{ marginTop: '30px', textAlign: 'center', fontSize: '20px', fontWeight: 'bold', color: '#ffcc00' }}>
          Prediction: {result}
        </div>
      )}
    </div>
  );
};

export default Dashboard;
